// Express: strong ETags, and an automatic 304 when If-None-Match matches
const express = require('express');
const app = express();
app.set('etag', 'strong');

app.get('/chairs/:slug', async (req, res) => {
  const html = await renderChairPage(req.params.slug); // your server-side renderer
  res.set('Cache-Control', 'no-cache'); // may be stored, but must be revalidated
  res.type('html').send(html); // res.send() compares the ETag and answers 304 when fresh
});

// Pages with a per-request nonce or CSRF token: an ETag from the data, not from the body
const crypto = require('crypto');
const TEMPLATE_VERSION = '2026-10-02';
app.get('/products/:slug', async (req, res) => {
  const product = await loadProduct(req.params.slug); // your data access
  const etag = '"' + crypto.createHash('sha256').update(JSON.stringify(product) + TEMPLATE_VERSION).digest('hex').slice(0, 16) + '"';
  res.set('ETag', etag);
  res.set('Cache-Control', 'no-cache');
  if (req.fresh) return res.status(304).end(); // If-None-Match matches the data ETag
  res.type('html').send(renderProductPage(product, res.locals.cspNonce));
});

const ORIGIN = 'https://www.example.com';
// Parameters each route actually uses, in the order they must appear.
const PARAMS = { '/chairs': ['colour', 'page'], '/search': ['q'] };

function expectedUrl(pathname, searchParams) {
  let path = pathname.toLowerCase().replace(/\/{2,}/g, '/');
  if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);
  const kept = new URLSearchParams();
  for (const name of PARAMS[path] || []) {
    const value = searchParams.get(name);
    if (value) kept.set(name, value); // unused and empty parameters are dropped
  }
  const query = kept.toString();      // spaces always come out as +
  return path + (query ? '?' + query : '');
}

app.set('trust proxy', true);         // so req.protocol is right behind a CDN or load balancer
app.use((req, res, next) => {
  const requested = new URL(ORIGIN + req.originalUrl); // not new URL(path, base): '//x' would parse as a host
  const expected = expectedUrl(requested.pathname, requested.searchParams);
  const wrongOrigin = req.protocol !== 'https' || req.hostname !== 'www.example.com';
  if (wrongOrigin || expected !== requested.pathname + requested.search) {
    return res.redirect(301, ORIGIN + expected); // one hop, straight to the final URL
  }
  next();
});

# Inside the server block: office documents out of the index.
# An add_header in a location replaces every add_header set at server level for those responses:
# repeat your HSTS and CSP lines in each such location (or use the headers-more module).
location ~* \.(pdf|docx?|xlsx?)$ {
    add_header X-Robots-Tag "noindex" always;
    add_header Strict-Transport-Security "max-age=31536000" always;  # repeated from the server block
}

# Images that must not appear in Google Images (they still display on your pages)
location ^~ /internal-images/ {
    add_header X-Robots-Tag "noindex" always;
    add_header Strict-Transport-Security "max-age=31536000" always;  # repeated from the server block
}

# http:// on both host names -> https://www. in one hop
server {
    listen 80;
    server_name example.com www.example.com;
    return 301 https://www.example.com$request_uri;
}

# https:// on the bare domain -> https://www.
server {
    listen 443 ssl;
    server_name example.com;
    ssl_certificate     /etc/ssl/example.com.crt;
    ssl_certificate_key /etc/ssl/example.com.key;
    return 301 https://www.example.com$request_uri;
}

server {
    listen 443 ssl;
    http2 on;  # nginx 1.25.1+; older versions use "listen 443 ssl http2;"
    server_name www.example.com;
    ssl_certificate     /etc/ssl/www.example.com.crt;
    ssl_certificate_key /etc/ssl/www.example.com.key;

    # Moved pages: permanent and straight to the final URL
    location = /old-chairs/ {
        return 301 https://www.example.com/chairs/;
    }
    location ^~ /shop/chairs/ {
        rewrite ^/shop/chairs/(.*)$ https://www.example.com/chairs/$1 permanent;
    }

    root /var/www/example;
}

# check_chain.py  -  usage: python check_chain.py https://www.example.com/page [more URLs]
import sys
from urllib.parse import urljoin, urlsplit

import requests
from protego import Protego

AGENTS = {
    "googlebot": "Mozilla/5.0 (compatible; Googlebot/2.1; +http://www.google.com/bot.html)",
    "browser": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/140.0 Safari/537.36",
}
TOKEN = "Googlebot"  # the robots.txt token the rules are tested for
_robots = {}


def robots_for(url):
    parts = urlsplit(url)
    origin = f"{parts.scheme}://{parts.netloc}"
    if origin not in _robots:
        r = requests.get(origin + "/robots.txt", headers={"User-Agent": AGENTS["googlebot"]}, timeout=10)
        if r.status_code == 200:
            text = r.text
        elif 400 <= r.status_code < 500 and r.status_code != 429:
            text = ""  # 4xx (except 429): Google crawls as if there were no robots.txt
        else:
            text = "User-agent: *\nDisallow: /"  # 5xx or 429: Google stops crawling the host for now
        _robots[origin] = Protego.parse(text)
    return _robots[origin]


def check(url, agent, max_hops=10):
    print(f"[{agent}]")
    for hop in range(max_hops + 1):
        allowed = robots_for(url).can_fetch(url, TOKEN)
        print(f"  {hop}: {'allowed' if allowed else 'BLOCKED by robots.txt'}  {url}")
        if not allowed:
            print("     crawling stops here; Search Console reports the first URL of the chain as blocked")
            return
        r = requests.get(url, headers={"User-Agent": AGENTS[agent]}, allow_redirects=False, timeout=10)
        location = r.headers.get("Location")
        if r.status_code in (301, 302, 303, 307, 308) and location:
            url = urljoin(url, location)
        else:
            print(f"     final status {r.status_code}")
            return
    print(f"     more than {max_hops} redirect hops")


if __name__ == "__main__":
    for start in sys.argv[1:]:
        for agent in AGENTS:  # different chains for the two user agents point to cloaking
            check(start, agent)

// Server (Express 4 or 5): static files first, then a final handler for every other path
const express = require('express');
const path = require('path');
const app = express();
const shell = path.join(__dirname, 'dist', 'index.html');
const notFound = path.join(__dirname, 'dist', '404.html'); // static error page: no router script
const PAGES = [/^\/$/, /^\/chairs\/$/, /^\/tables\/$/, /^\/about\/$/];
const PRODUCT = /^\/chairs\/([a-z0-9-]+)$/;

app.use(express.static(path.join(__dirname, 'dist'), { index: false }));

app.use(async (req, res) => {
  const product = req.path.match(PRODUCT);
  const found = PAGES.some((re) => re.test(req.path)) || (product !== null && (await productExists(product[1])));
  if (found) res.sendFile(shell);
  else res.status(404).sendFile(notFound); // also answers /not-found, the target of the client fallback
});

